    if filename.startswith('.') and filename.count('.') == 1:
        return ''
    parts = filename.rsplit('.', 1)
    if len(parts) > 1:
        return '.' + parts[1]
    return ''

def format_placeholder(value, padding):
    try:
        if isinstance(value, int) or (isinstance(value, str) and value.isdigit()):
            ival = int(value)
            if ival >= 0:
                return str(ival).zfill(padding)
            else:
                return str(ival)
        return str(value)
    except:
        return str(value)

