        print("nomino 1.6.4")
        sys.exit(0)

    # Validate arguments
    source = None
    output_pattern = None

    if args.map:
        if args.regex or args.sort or args.args:
            # Actually, the original tool might allow some combinations
            pass
    elif args.regex or args.sort:
        if len(args.args) == 1:
            output_pattern = args.args[0]
        elif len(args.args) > 1:
            print("error: optional SOURCE must be used without setting regex, map or sort flags")
            sys.exit(1)
        elif not args.regex and args.sort:
            # sort mode requires at least output_pattern
            if not args.args:
                print("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.")
                sys.exit(1)
    else:
        if len(args.args) >= 2:
            source = args.args[-2]
            output_pattern = args.args[-1]
        elif len(args.args) == 1:
            # If only one arg and no flags, it's still an error because SOURCE is missing
            print("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.")
            sys.exit(1)
        else:
            print("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.")
            sys.exit(1)

    working_dir = args.dir

    # Collect files
    files_to_process = []
    if args.map:
        try:
            with open(os.path.join(working_dir, args.map), 'r') as f:
                mapping = json.load(f)
                for old, new in mapping.items():
                    files_to_process.append((old, new))
        except Exception as e:
            # print(f"[error] unable to read map file: {e}")
            sys.exit(1)
    else:
        # Determine files and regex
        regex_pattern = args.regex or source
        effective_max_depth = 0
        if args.max_depth is not None:
            effective_max_depth = args.max_depth
        elif args.depth is not None:
            effective_max_depth = args.depth # This is not exactly correct but close
        elif regex_pattern and '/' in regex_pattern:
            effective_max_depth = regex_pattern.count('/')

        # Walk directory
        all_items = []
        if effective_max_depth > 0:
            for root, dirs, files in os.walk(working_dir):
                rel_root = os.path.relpath(root, working_dir)
                if rel_root == '.':
                    rel_root = ''

                depth = rel_root.count('/') + 1 if rel_root else 0
                if depth > effective_max_depth:
                    continue

                for item in dirs + files:
                    item_path = os.path.join(rel_root, item)
                    all_items.append(item_path)
        else:
            all_items = os.listdir(working_dir)

        if args.sort:
            all_items.sort(key=natural_key, reverse=(args.sort == 'desc'))
        else:
            all_items.sort() # Default sort for regex? Actually I saw lexicographical.

        compiled_re = None
        if regex_pattern:
            try:
                # Original nomino seems to match from start of string usually?
                # No, I saw "a" matching "ab.txt" and becoming "b.txt". 
                # That means it's not anchored.
                compiled_re = re.compile(regex_pattern)
            except:
                print(f"error: invalid regex pattern '{regex_pattern}'")
                sys.exit(1)

        enum_index = 1
        for item in all_items:
            # Original tool seems to ignore some things? No.
            # Match item
            groups = {0: item}
            match = None
            if compiled_re:
                match = compiled_re.search(item)
                if not match:
                    continue
                # Fill groups
                groups.update({i: match.group(i) for i in range(len(match.groups()) + 1)})
                groups.update(match.groupdict())
            elif args.sort:
                # In sort mode, group 1 is the enumerator
                groups[1] = enum_index
                enum_index += 1
            else:
                # Source mode without explicit -r
                match = compiled_re.search(item) if compiled_re else (re.search(regex_pattern, item) if regex_pattern else None)
                if not match:
                    continue
                groups.update({i: match.group(i) for i in range(len(match.groups()) + 1)})
                groups.update(match.groupdict())

            # Apply output pattern
            new_name = output_pattern

            # Find all placeholders {G:P} or {}
            def replace_placeholder(m):
                content = m.group(1)
                auto_idx = [0] # Use a list for closure mutation
                if not content:
                    # {} case
                    # This is tricky because the auto_index should increment for each {}
                    # I'll handle this outside re.sub
                    return m.group(0)

                parts = content.split(':')
                g = parts[0]
                p = int(parts[1]) if len(parts) > 1 else 0

                val = ""
                if not g:
                    # {:P} case
                    return m.group(0)

                if g.isdigit():
                    val = groups.get(int(g), "")
                else:
                    val = groups.get(g, "")

                return format_placeholder(val, p)

            # Manual replacement to handle auto-incrementing {} correctly
            auto_idx = 1
            res_name = ""
            last_pos = 0
            for m in re.finditer(r'\{([^{}]*)\}', new_name):
                res_name += new_name[last_pos:m.start()]
                content = m.group(1)
                parts = content.split(':')
                g = parts[0]
                p = int(parts[1]) if len(parts) > 1 else 0

                if not g:
                    # {} or {:P} case
                    idx = auto_idx
                    auto_idx += 1
                    # In sort mode, if no regex, the "group" is the enum_index
                    if args.sort and not args.regex:
                        val = groups.get(1, "") # enum_index was already put in group 1
                    else:
                        val = groups.get(idx, "")
