                    val = groups.get(int(g), "")
                else:
                    val = groups.get(g, "")

                res_name += format_placeholder(val, p)
                last_pos = m.end()
            res_name += new_name[last_pos:]

            # Extension preservation
            if not args.no_extension:
                ext = get_extension(item)
                res_name += ext

            files_to_process.append((item, res_name))

