    renames = []
    output_files = set(os.listdir(working_dir))
    if not args.test:
        # In a real run, we need to be careful.
        # But for now, let's just compute the final names.
        pass

    final_renames = []
    for old, new in files_to_process:
        target = new
        if not args.overwrite and target != old:
            actual_target = target
            while actual_target in output_files:
                # Prepend _ to the filename but keep directory
                path_parts = list(os.path.split(actual_target))
                path_parts[-1] = '_' + path_parts[-1]
                actual_target = os.path.join(*path_parts)
            target = actual_target

        final_renames.append((old, target))
        if not args.test:
            output_files.add(target)
            if old in output_files:
                output_files.remove(old)

    # Print table
    if not args.quiet:
        if final_renames:
            # Determine widths
            w1 = max(len("Input"), max(len(r[0]) for r in final_renames))
            w2 = max(len("Output"), max(len(r[1]) for r in final_renames))

            sep = f"+{'-'*(w1+2)}+{'-'*(w2+2)}+"
            print(sep)
            print(f"| {'Input'.ljust(w1)} | {'Output'.ljust(w2)} |")
            print(sep)
            for old, new in final_renames:
                print(f"| {old.ljust(w1)} | {new.ljust(w2)} |")
            print(sep)

    # Execute renames
    undo_map = {}
    if not args.test:
        for old, new in final_renames:
            if old == new:
                continue

            old_full = os.path.join(working_dir, old)
            new_full = os.path.join(working_dir, new)

            if args.mkdir:
                os.makedirs(os.path.dirname(new_full), exist_ok=True)

            try:
                # If target directory doesn't exist and -k is not set, this will fail
                os.rename(old_full, new_full)
                undo_map[new] = old
            except Exception as e:
                print(f"[error] unable to rename '{old}': {e.strerror} (os error {e.errno})")

    if args.generate:
        with open(os.path.join(working_dir, args.generate), 'w') as f:
            json.dump(undo_map, f, indent=2)

if __name__ == "__main__":
    main()
