        if args.sort:
            all_items.sort(key=natural_key, reverse=(args.sort == 'desc'))
        else:
            all_items.sort()

        compiled_re = None
        if regex_pattern:
            try:
                compiled_re = re.compile(regex_pattern)
            except:
                print(f"error: invalid regex pattern '{regex_pattern}'", file=sys.stderr)
                sys.exit(1)

        enum_idx = 1
        for item in all_items:
            groups = {0: item}
            if compiled_re:
                match = compiled_re.search(item)
                if not match: continue
                groups.update({i: match.group(i) for i in range(len(match.groups()) + 1)})
                groups.update(match.groupdict())
            elif args.sort:
                groups[1] = enum_idx
                enum_idx += 1

            res_name = ""
            last_pos = 0
            auto_idx = 1
            for m in re.finditer(r'\{([^{}]*)\}', output_pattern):
                res_name += output_pattern[last_pos:m.start()]
                content = m.group(1)
                parts = content.split(':')
                g = parts[0]
                p = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 0
                if not g:
                    val = groups.get(auto_idx, "")
                    auto_idx += 1
                elif g.isdigit():
                    val = groups.get(int(g), "")
                else:
                    val = groups.get(g, "")
                res_name += format_placeholder(val, p)
                last_pos = m.end()
            res_name += output_pattern[last_pos:]
            if not args.no_extension:
                res_name += get_extension(item)
            files_to_process.append((item, res_name))

    final_renames = []
    output_files_in_dir = set(os.listdir(working_dir))
    for old, new in files_to_process:
        target = new
        if not args.overwrite and old != target:
            while target in output_files_in_dir:
                head, tail = os.path.split(target)
                target = os.path.join(head, '_' + tail)
        final_renames.append((old, target))
        if not args.test:
            if old in output_files_in_dir: output_files_in_dir.remove(old)
            output_files_in_dir.add(target)

    if not args.quiet and final_renames:
        w1 = max(len("Input"), max(len(r[0]) for r in final_renames))
        w2 = max(len("Output"), max(len(r[1]) for r in final_renames))
        sep = f"+{'-'*(w1+2)}+{'-'*(w2+2)}+"
        print(sep)
        print(f"| {'Input'.ljust(w1)} | {'Output'.ljust(w2)} |")
        print(sep)
        for old, new in final_renames:
            print(f"| {old.ljust(w1)} | {new.ljust(w2)} |")
        print(sep)

    undo_map = {}
    if not args.test:
        for old, new in final_renames:
            if old == new: continue
            try:
                old_p = os.path.join(working_dir, old)
                new_p = os.path.join(working_dir, new)
                if args.mkdir: os.makedirs(os.path.dirname(new_p), exist_ok=True)
                os.rename(old_p, new_p)
                undo_map[new] = old
            except Exception as e:
                print(f"[error] unable to rename '{old}': {e.strerror} (os error {e.errno})", file=sys.stderr)
        if args.generate:
            with open(os.path.join(working_dir, args.generate), 'w') as f:
                json.dump(undo_map, f, indent=2)

if __name__ == "__main__":
    main()
